DICT_TOPIC = dict(id="dict", level=2, title="Từ điển (dict)", summary="Dict lưu các cặp **khóa → giá trị**; tra cứu theo khóa rất nhanh `O(1)`. Học theo các thao tác: **tạo → truy cập → duyệt → thêm → sửa → xóa → kiểm tra → gộp**.",
 blocks=[
  ("table", ["Thao tác", "Cú pháp chính"], [
    ["Tạo", "`d = {\"a\": 1}`, `{}`, `dict(a=1)`"],
    ["Truy cập", "`d[k]`, `d.get(k, mac_dinh)`"],
    ["Duyệt", "`for k in d:`, `d.items()`, `d.values()`"],
    ["Thêm / sửa", "`d[k] = v`, `d.update(...)`, `d.setdefault(k, v)`"],
    ["Xóa", "`d.pop(k)`, `del d[k]`, `d.clear()`"],
    ["Kiểm tra", "`k in d`, `len(d)`"],
    ["Gộp / sao chép", "`d1 | d2`, `d.copy()`"],
  ]),
  ("p", "**Khóa** phải là kiểu bất biến (chuỗi, số, tuple) và **không trùng nhau**; **giá trị** có thể là bất kỳ kiểu gì (kể cả list, dict)."),
  OP("Thao tác 1 · Tạo từ điển"),
  ("ex", "Các cách tạo dict", "sv = {\"ten\": \"An\", \"tuoi\": 16}        # liệt kê cặp khóa: giá trị\nrong = {}                                # dict rỗng\nd2 = dict(ten=\"Binh\", tuoi=17)           # dùng dict()\nd3 = dict(zip([\"a\", \"b\"], [1, 2]))       # ghép hai list\nd4 = {x: x * x for x in range(1, 5)}     # dict comprehension\nprint(sv, rong, d2, d3, d4, sep=\"\\n\")", {}),
  OP("Thao tác 2 · Truy cập giá trị"),
  ("ex", "Truy cập bằng khóa", "sv = {\"ten\": \"An\", \"tuoi\": 16}\nprint(sv[\"ten\"])\nprint(len(sv))        # số cặp khóa-giá trị", {}),
  ("ex", "get(): lấy an toàn, không báo lỗi", "d = {\"a\": 1}\nprint(d.get(\"a\"))        # 1\nprint(d.get(\"b\"))        # None — khóa không có\nprint(d.get(\"b\", 0))     # 0 — giá trị mặc định tự đặt", {}),
  ("warn", "`d[\"b\"]` khi khóa `\"b\"` không tồn tại gây `KeyError`. Dùng `d.get(\"b\", mac_dinh)` hoặc kiểm tra `\"b\" in d` trước."),
  OP("Thao tác 3 · Duyệt từ điển"),
  ("ex", "Duyệt khóa (mặc định)", "d = {\"a\": 1, \"b\": 2, \"c\": 3}\nfor k in d:\n    print(k)", {}),
  ("ex", "Duyệt giá trị: values()", "d = {\"a\": 1, \"b\": 2, \"c\": 3}\nfor v in d.values():\n    print(v)\nprint(sum(d.values()))", {}),
  ("ex", "Duyệt cặp khóa - giá trị: items()", "d = {\"a\": 1, \"b\": 2}\nfor k, v in d.items():\n    print(k, v)", {}),
  ("ex", "Duyệt theo thứ tự khóa", "d = {\"cam\": 3, \"tao\": 5, \"le\": 2}\nfor k in sorted(d):\n    print(k, d[k])\nprint(sorted(d.items(), key=lambda kv: kv[1], reverse=True))   # theo giá trị giảm dần", {}),
  OP("Thao tác 4 · Thêm cặp mới"),
  ("ex", "Gán vào khóa mới", "sv = {\"ten\": \"An\"}\nsv[\"lop\"] = \"10A1\"       # khóa chưa có → thêm mới\nsv[\"tuoi\"] = 16\nprint(sv)", {}),
  ("ex", "update(): thêm nhiều cặp một lúc", "sv = {\"ten\": \"An\"}\nsv.update({\"lop\": \"10A1\", \"tuoi\": 16})\nprint(sv)", {}),
  ("ex", "setdefault(): chỉ thêm khi khóa chưa có", "d = {\"a\": 1}\nd.setdefault(\"a\", 100)    # đã có → giữ nguyên\nd.setdefault(\"b\", 2)      # chưa có → thêm\nprint(d)", {}),
  ("ex", "Xây dict từ dữ liệu: đếm tần suất", "arr = [\"cam\", \"tao\", \"cam\", \"le\", \"tao\", \"cam\"]\ndem = {}\nfor x in arr:\n    dem[x] = dem.get(x, 0) + 1     # chưa có thì coi như 0\nprint(dem)", {}),
  ("ex", "Gom nhóm: giá trị là một list", "hs = [(\"An\", \"10A1\"), (\"Binh\", \"10A2\"), (\"Chi\", \"10A1\")]\nnhom = {}\nfor ten, lop in hs:\n    nhom.setdefault(lop, []).append(ten)\nprint(nhom)", {}),
  OP("Thao tác 5 · Thay đổi giá trị"),
  ("ex", "Gán lại giá trị cho khóa đã có", "sv = {\"ten\": \"An\", \"tuoi\": 16}\nsv[\"tuoi\"] = 17          # khóa đã có → ghi đè giá trị\nsv[\"tuoi\"] += 1          # cập nhật theo giá trị cũ\nprint(sv)", {}),
  ("ex", "Đổi giá trị của mọi khóa", "gia = {\"cam\": 10, \"tao\": 20}\nfor k in gia:\n    gia[k] = gia[k] * 2     # tăng giá gấp đôi\nprint(gia)", {}),
  ("tip", "Dùng chung một cú pháp `d[k] = v` cho cả **thêm mới** lẫn **sửa**: khóa chưa có thì thêm, đã có thì ghi đè."),
  OP("Thao tác 6 · Xóa phần tử"),
  ("ex", "pop(): xóa và lấy giá trị ra", "d = {\"a\": 1, \"b\": 2, \"c\": 3}\nv = d.pop(\"a\")\nprint(v, d)\nprint(d.pop(\"z\", \"khong co\"))    # có giá trị mặc định thì không báo lỗi", {}),
  ("ex", "del và clear()", "d = {\"a\": 1, \"b\": 2, \"c\": 3}\ndel d[\"b\"]\nprint(d)\nd.clear()\nprint(d)", {}),
  ("ex", "Xóa mọi cặp thỏa điều kiện (tạo dict mới)", "diem = {\"An\": 8, \"Binh\": 4, \"Chi\": 9, \"Dung\": 3}\ndau = {k: v for k, v in diem.items() if v >= 5}\nprint(dau)", {}),
  ("warn", "Không thêm/xóa khóa trong lúc đang `for k in d:` trên chính dict đó (báo `RuntimeError`). Hãy duyệt trên `list(d)` hoặc tạo dict mới."),
  OP("Thao tác 7 · Kiểm tra & tìm kiếm"),
  ("ex", "Kiểm tra khóa tồn tại: in / not in", "d = {\"a\": 1, \"b\": 2}\nprint(\"a\" in d)            # kiểm tra KHÓA\nprint(\"z\" not in d)\nprint(2 in d.values())      # kiểm tra GIÁ TRỊ\nif \"c\" not in d:\n    d[\"c\"] = 3\nprint(d)", {}),
  ("ex", "Tìm khóa có giá trị lớn nhất", "diem = {\"An\": 8, \"Binh\": 9, \"Chi\": 7}\ntot_nhat = max(diem, key=diem.get)\nprint(tot_nhat, diem[tot_nhat])", {}),
  OP("Thao tác 8 · Sao chép & gộp"),
  ("ex", "copy() và gộp hai dict", "a = {\"x\": 1, \"y\": 2}\nb = {\"y\": 20, \"z\": 30}\nc = a.copy()               # bản sao thật\ngop = a | b                # khóa trùng: lấy giá trị của b\nprint(c, gop)\na.update(b)                # gộp thẳng vào a\nprint(a)", {}),
  OP("Tổng hợp & mở rộng"),
  ("table", ["Cú pháp", "Tác dụng"], [
    ["`d[k]`", "Lấy giá trị (không có khóa: `KeyError`)"],
    ["`d.get(k, mac_dinh)`", "Lấy giá trị an toàn"],
    ["`k in d`", "Kiểm tra khóa có tồn tại"],
    ["`d.keys()` `d.values()` `d.items()`", "Các khóa / giá trị / cặp (khóa, giá trị)"],
    ["`d.pop(k)`", "Xóa khóa và trả về giá trị"],
    ["`del d[k]`", "Xóa khóa"],
    ["`d.update(d2)`", "Gộp / cập nhật nhiều cặp"],
    ["`d.setdefault(k, v)`", "Thêm `k: v` nếu `k` chưa có"],
  ]),
  ("ex", "Dict lồng nhau: danh sách học sinh", "lop = {\n    \"An\": {\"toan\": 8, \"tin\": 9},\n    \"Binh\": {\"toan\": 7, \"tin\": 10},\n}\nlop[\"An\"][\"tin\"] = 10                 # sửa điểm\nlop[\"Chi\"] = {\"toan\": 9, \"tin\": 8}      # thêm học sinh\nfor ten, d in lop.items():\n    print(ten, sum(d.values()) / len(d))", {}),
 ])
